import{_ as d,o as e,c as a,ag as i}from"./chunks/framework.BwSLX4ak.js";const s=JSON.parse('{"title":"平台兼容性","description":"","frontmatter":{},"headers":[],"relativePath":"shitbot/compatibility.md","filePath":"shitbot/compatibility.md"}'),r={name:"shitbot/compatibility.md"};function o(l,t,h,n,c,p){return e(),a("div",null,[...t[0]||(t[0]=[i('<h1 id="平台兼容性" tabindex="-1">平台兼容性 <a class="header-anchor" href="#平台兼容性" aria-label="Permalink to &quot;平台兼容性&quot;">​</a></h1><h2 id="平台与-java" tabindex="-1">平台与 Java <a class="header-anchor" href="#平台与-java" aria-label="Permalink to &quot;平台与 Java&quot;">​</a></h2><table tabindex="0"><thead><tr><th>平台模块</th><th>运行位置</th><th>插件最低 Java</th><th>主要用途</th></tr></thead><tbody><tr><td>ShitBotSpigot</td><td>Spigot、Paper、Folia、CatServer 等 Bukkit 服务端</td><td>8</td><td>单服运行，或作为代理后的 Bukkit 后端</td></tr><tr><td>ShitBotBungee</td><td>BungeeCord</td><td>8</td><td>群组服代理、OneBot、跨服转发和后端命令调度</td></tr><tr><td>ShitBotVelocity</td><td>Velocity</td><td>21</td><td>群组服代理、OneBot、跨服转发和后端命令调度</td></tr><tr><td>ShitBotNukkit</td><td>Nukkit-MOT</td><td>17</td><td>Nukkit-MOT 单服运行</td></tr></tbody></table><p>服务端核心自身可能要求更高版本的 Java。例如现代 Paper 通常不能因为 ShitBotSpigot 兼容 Java 8 就改用 Java 8 启动。</p><h2 id="已验证环境" tabindex="-1">已验证环境 <a class="header-anchor" href="#已验证环境" aria-label="Permalink to &quot;已验证环境&quot;">​</a></h2><p>当前仓库明确记录过以下验证环境：</p><ul><li>Spigot 1.8.8；</li><li>Spigot 1.12.2；</li><li>Paper 1.21；</li><li>Paper 1.21.11；</li><li>Paper 26.1；</li><li>Folia 1.21.11；</li><li>CatServer 1.12.2；</li><li>BungeeCord <code>26.1-R0.1-SNAPSHOT</code> 构建线；</li><li>Velocity 多版本运行线；</li><li>Nukkit-MOT，模块当前编译依赖为 <code>1.26.40-R1</code>。</li></ul><p>这些记录表示项目在对应环境中做过适配或验证，不代表任意服务端核心、插件组合和 Mod 混合环境都具有完全相同行为。出现兼容问题时，请提供精确核心名称、版本和完整启动日志。</p><h2 id="平台功能差异" tabindex="-1">平台功能差异 <a class="header-anchor" href="#平台功能差异" aria-label="Permalink to &quot;平台功能差异&quot;">​</a></h2><table tabindex="0"><thead><tr><th>功能</th><th>Spigot standalone</th><th>Spigot backend</th><th>BungeeCord / Velocity</th><th>Nukkit-MOT</th></tr></thead><tbody><tr><td>直接连接 OneBot</td><td>支持</td><td>不连接</td><td>支持</td><td>支持</td></tr><tr><td>玩家登录绑定检查</td><td>支持</td><td>支持</td><td>代理侧支持</td><td>支持</td></tr><tr><td>群服互通</td><td>支持</td><td>由代理负责</td><td>支持</td><td>支持文本和 URL</td></tr><tr><td>保存在线背包快照</td><td>支持</td><td>支持</td><td>不直接读取在线背包</td><td>支持</td></tr><tr><td>从共享数据库生成背包图</td><td>支持</td><td>支持</td><td>支持</td><td>支持</td></tr><tr><td>代理—后端命令通道</td><td>可作为后端</td><td>监听代理请求</td><td>调度到后端</td><td>不使用</td></tr><tr><td>PictureBridge 媒体标记</td><td>支持</td><td>由代理消息入口决定</td><td>支持</td><td>不使用</td></tr><tr><td>高级 Java2D 场景模板</td><td>支持</td><td>可提供后端数据</td><td>支持</td><td>支持，不支持 Bukkit PAPI</td></tr><tr><td>PlaceholderAPI 模板数据</td><td>本服解析</td><td>解析代理请求</td><td>转发到指定 Spigot 后端</td><td>不支持</td></tr></tbody></table><p>后端模式的 Spigot 不连接 OneBot，避免代理与子服重复回复同一条 QQ 消息。</p><h2 id="folia" tabindex="-1">Folia <a class="header-anchor" href="#folia" aria-label="Permalink to &quot;Folia&quot;">​</a></h2><p>Spigot 模块在插件描述中声明 <code>folia-supported: true</code>。玩家背包字段会在 Bukkit 主线程或 Folia 玩家所属区域线程复制，数据库、资源扫描和图片渲染在异步线程执行。</p><p>其他插件通过非 Folia 安全方式修改背包、权限或日志时，仍可能影响对应联动功能。</p><h2 id="可选依赖" tabindex="-1">可选依赖 <a class="header-anchor" href="#可选依赖" aria-label="Permalink to &quot;可选依赖&quot;">​</a></h2><p>ShitBot 的基础运行不强制要求这些插件，但安装后可以扩展权限或数据来源：</p><table tabindex="0"><thead><tr><th>插件</th><th>使用位置</th><th>用途</th></tr></thead><tbody><tr><td>LuckPerms</td><td>Spigot、BungeeCord、Velocity、Nukkit-MOT</td><td>查询离线角色权限</td></tr><tr><td>Vault</td><td>Spigot</td><td>LuckPerms 不可用时查询离线权限</td></tr><tr><td>Essentials / EssentialsX</td><td>Spigot</td><td>优先读取服务端 TPS 数据</td></tr><tr><td>PlaceholderAPI</td><td>Spigot</td><td>为明确声明 <code>papi</code> 提供器的高级图片模板批量解析变量</td></tr></tbody></table><p>没有可选权限插件时，在线玩家仍使用平台权限系统；离线角色的权限判断能力会受限。</p><h2 id="onebot" tabindex="-1">OneBot <a class="header-anchor" href="#onebot" aria-label="Permalink to &quot;OneBot&quot;">​</a></h2><p>ShitBot 使用 OneBot v11 正向 WebSocket，需要 OneBot 实现支持：</p><ul><li>群消息事件；</li><li>发送群消息；</li><li>发送图片消息段；</li><li>Action 回执；</li><li>Access Token 鉴权时接受 <code>Authorization: Bearer</code> 请求头。</li></ul><p>不同 OneBot 实现对文件、视频、语音、分享卡片和临时媒体 URL 的字段可能不同。ShitBot 会尽量转换为游戏内标签；无法取得 URL 时只显示可用摘要。</p><h2 id="picturebridge" tabindex="-1">PictureBridge <a class="header-anchor" href="#picturebridge" aria-label="Permalink to &quot;PictureBridge&quot;">​</a></h2><p>Java 客户端使用 <code>forwarding.group-to-game.media-mode: &quot;picturebridge&quot;</code> 时，可以安装独立的 <a href="https://github.com/hutuyee/PictureBridge" target="_blank" rel="noreferrer">PictureBridge</a> 客户端模组。</p><p>PictureBridge 不会被打包进 ShitBot 服务端 JAR。Nukkit-MOT 不使用该客户端协议。</p>',25)])])}const b=d(r,[["render",o]]);export{s as __pageData,b as default};
